// layout decides scrollbar visibility (Textual's overflow + auto-auto
// interplay) and returns the resulting content area and which bars show.
func (m Model) layout() (contentW, contentH int, showV, showH bool) {
	fullW, fullH := m.width, m.height
	if fullW <= 0 || fullH <= 0 {
		return fullW, fullH, false, false
	}
	vH := m.vp.TotalLineCount()
	vW := m.virtualW

	showV = m.overflowY == OverflowScroll || (m.overflowY == OverflowAuto && vH > fullH)
	showH = m.overflowX == OverflowScroll || (m.overflowX == OverflowAuto && vW > fullW)
	// Showing one bar shrinks the other axis and may force the second (auto).
	if m.overflowX == OverflowAuto && showV && !showH {
		showH = vW > fullW-scrollbar.VThickness
	}
	if m.overflowY == OverflowAuto && showH && !showV {
		showV = vH > fullH-scrollbar.HThickness
	}
	if m.overflowY == OverflowHidden {
		showV = false
	}
	if m.overflowX == OverflowHidden {
		showH = false
	}

	contentW, contentH = fullW, fullH
	if showV {
		contentW -= scrollbar.VThickness
	}
	if showH {
		contentH -= scrollbar.HThickness
	}
	return contentW, contentH, showV, showH
}

// handleMouse updates hover / grab state from a mouse event and, while grabbed,
// drives the scroll offset. It mirrors Textual's ScrollBar interaction: pressing
// the thumb grabs it and drags *relative* to the grab point (no jump), while
// pressing the track above / below the thumb pages one window toward the press
// (ScrollBarRender's scroll_up / scroll_down actions → scroll_page_*) WITHOUT
// grabbing — so a held track press neither repeats nor drags (Textual oracle,
// widget/internal/trackpress). Hover requires all-motion mouse reporting (see
// View) so bare pointer motion recolours the thumb.
func (m Model) handleMouse(ms tea.Mouse, click, release bool) Model {
	cw, ch, showV, showH := m.layout()
	relX, relY := ms.X-m.originX, ms.Y-m.originY

	overV := showV && relX >= cw && relX < cw+scrollbar.VThickness && relY >= 0 && relY < ch
	overH := showH && relY >= ch && relY < ch+scrollbar.HThickness && relX >= 0 && relX < cw

	if release {
		m.grabbed = sbNone
		return m
	}

	switch {
	case overV:
		m.hovered = sbVertical
	case overH:
		m.hovered = sbHorizontal
	default:
		if m.grabbed == sbNone {
			m.hovered = sbNone
		}
	}

	// A left-press over a bar: on the thumb it anchors a relative drag without
	// moving; on the track it pages one window (the viewport setters clamp) and
	// leaves the bar ungrabbed, so the drag block below does nothing.
	if click && ms.Button == tea.MouseLeft {
		switch {
		case overV:
			start, end := scrollbar.ThumbExtent(ch, m.vp.TotalLineCount(), m.vp.YOffset())
			switch {
			case start > end: // no thumb drawn: Textual's bar carries no actions
			case relY < start:
				m.vp.SetYOffset(m.vp.YOffset() - ch)
			case relY > end:
				m.vp.SetYOffset(m.vp.YOffset() + ch)
			default:
				m.grabbed = sbVertical
				m.grabAnchor, m.grabBase = relY, m.vp.YOffset()
			}
		case overH:
			start, end := scrollbar.ThumbExtent(cw, m.virtualW, m.vp.XOffset())
			switch {
			case start > end:
			case relX < start:
				m.vp.SetXOffset(m.vp.XOffset() - cw)
			case relX > end:
				m.vp.SetXOffset(m.vp.XOffset() + cw)
			default:
				m.grabbed = sbHorizontal
				m.grabAnchor, m.grabBase = relX, m.vp.XOffset()
			}
		}
	}

	// Drag: pointer movement from the grab anchor drives the scroll offset, scaled
	// by virtual/window (Textual ScrollBar._on_mouse_move). On the press frame the
	// pointer equals the anchor, so the offset holds at grabBase (no jump).
	switch m.grabbed {
	case sbVertical:
		if ch > 0 {
			delta := float64(relY-m.grabAnchor) * float64(m.vp.TotalLineCount()) / float64(ch)
			m.vp.SetYOffset(m.grabBase + int(math.Round(delta)))
		}
	case sbHorizontal:
		if cw > 0 {
			delta := float64(relX-m.grabAnchor) * float64(m.virtualW) / float64(cw)
			m.vp.SetXOffset(m.grabBase + int(math.Round(delta)))
		}
	}
	return m
}

// Render assembles the content, the visible scrollbars, and the corner.
func (m Model) Render() string {
	cw, ch, showV, showH := m.layout()
	if cw <= 0 || ch <= 0 {
		return ""
	}

	vp := m.vp
	vp.SetWidth(cw)
	vp.SetHeight(ch)
	vp.SetYOffset(vp.YOffset()) // clamp to the current geometry (see settled)
	vp.SetXOffset(vp.XOffset())
	body := vp.View()

	if showV {
		vbar := m.renderVerticalBar(ch, vp.TotalLineCount(), vp.YOffset())
		body = lipgloss.JoinHorizontal(lipgloss.Top, body, vbar)
	}
	if showH {
		hbar := m.renderHorizontalBar(cw, m.virtualW, vp.XOffset())
		if showV {
			hbar = lipgloss.JoinHorizontal(lipgloss.Top, hbar, m.renderCorner())
		}
		body = lipgloss.JoinVertical(lipgloss.Left, body, hbar)
	}
	return body
}

// View implements tea.Model (Bubble Tea v2). MouseModeAllMotion is requested so
// the host receives wheel + click/drag AND bare hover motion: the scrollbar's
// hover recolour (Textual's mouse_over → $scrollbar-hover) needs motion events
// with no button held, which button-event tracking (CellMotion) does not report.
func (m Model) View() tea.View {
	v := tea.NewView(m.Render())
	v.MouseMode = tea.MouseModeAllMotion
	return v
}

// thumbColor resolves the thumb colour for the given bar from its interaction
// state: resting $scrollbar, hovered $scrollbar-hover, grabbed $scrollbar-active.
func (m Model) thumbColor(target sbTarget) gocolor.Color {
	tok := style.Scrollbar
	if m.grabbed == target {
		tok = style.ScrollbarActive
	} else if m.hovered == target {
		tok = style.ScrollbarHover
	}
	return style.Active().Color(tok)
}

// renderVerticalBar paints the right-edge scrollbar via the reusable
// widget/scrollbar primitive, passing this container's interaction-resolved
// thumb colour and the theme track colour.
func (m Model) renderVerticalBar(length, virtual, position int) string {
	return scrollbar.RenderVertical(length, virtual, position,
		m.thumbColor(sbVertical), style.Active().Color(style.ScrollbarBackground))
}

// renderHorizontalBar paints the bottom-edge scrollbar via widget/scrollbar.
func (m Model) renderHorizontalBar(length, virtual, position int) string {
	return scrollbar.RenderHorizontal(length, virtual, position,
		m.thumbColor(sbHorizontal), style.Active().Color(style.ScrollbarBackground))
}

// renderCorner fills the gap where both scrollbars meet (Textual's
// ScrollBarCorner, filled with $scrollbar-corner-color).
func (m Model) renderCorner() string { return scrollbar.RenderCorner() }
